"use strict";

// Build the self-contained HTML used by the Streamlit deployment.
const fs = require("fs");
const path = require("path");

const root = __dirname;
const indexFile = path.join(root, "index.html");
const outputFile = path.join(root, "gilsaegim-standalone.html");

const mimeTypes = {
  ".gif": "image/gif",
  ".jpeg": "image/jpeg",
  ".jpg": "image/jpeg",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".webp": "image/webp"
};

function readText(filePath) {
  return fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, "");
}

function dataUri(filePath) {
  const mime = mimeTypes[path.extname(filePath).toLowerCase()] || "application/octet-stream";
  return `data:${mime};base64,${fs.readFileSync(filePath).toString("base64")}`;
}

function localFile(source) {
  const filePath = path.resolve(root, source.split("?", 1)[0]);
  const relative = path.relative(root, filePath);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`Path outside project: ${source}`);
  }
  return filePath;
}

function inlineStyles(html) {
  return html.replace(/<link\s+rel="stylesheet"\s+href="([^"]+)"\s*>/g, (_, sourceWithQuery) => {
    const source = sourceWithQuery.split("?", 1)[0];
    return `<style data-source="${source}">\n/* SOURCE: ${source} */\n${readText(localFile(source))}\n</style>`;
  });
}

function inlineScripts(html) {
  return html.replace(/<script\s+src="([^"]+)"\s*><\/script>/g, (_, sourceWithQuery) => {
    const source = sourceWithQuery.split("?", 1)[0];
    return `<script data-source="${source}">\n${readText(localFile(source))}\n</script>`;
  });
}

function inlineAssets(html) {
  const assetsDir = path.join(root, "assets");
  const candidates = [
    path.join(root, "truck-icon.svg"),
    ...fs.readdirSync(assetsDir).sort().map((name) => path.join(assetsDir, name))
  ];

  for (const filePath of candidates) {
    if (!fs.statSync(filePath).isFile()) continue;
    const relative = path.relative(root, filePath).split(path.sep).join("/");
    if (html.includes(relative)) html = html.split(relative).join(dataUri(filePath));
    const parentRelative = `../${relative}`;
    if (html.includes(parentRelative)) html = html.split(parentRelative).join(dataUri(filePath));
  }
  return html;
}

let html = readText(indexFile);
html = html.replace(/\s*<link\s+rel="manifest"\s+href="[^"]+"\s*>/, "");
html = inlineStyles(html);
html = inlineScripts(html);
html = inlineAssets(html);

const unresolved = ['href="css/', 'src="js/', 'src="assets/', 'href="assets/']
  .filter((marker) => html.includes(marker));
if (unresolved.length) throw new Error(`Unresolved local references: ${unresolved.join(", ")}`);

const banner = "<!-- Self-contained Streamlit bundle. Generated by build_streamlit_bundle.js; do not edit directly. -->\n";
html = html.replace(/<!doctype html>\s*/i, `<!doctype html>\n${banner}`);
fs.writeFileSync(outputFile, html, "utf8");
process.stdout.write(`Built ${path.basename(outputFile)}: ${fs.statSync(outputFile).size.toLocaleString()} bytes\n`);
